create table if not exists public.mansion_plots (
  plot              int primary key check (plot between 1 and 10),
  player_id         uuid not null unique references public.players (id) on delete cascade,
  stripe_session_id text not null,
  created_at        timestamptz not null default now()
);
alter table public.mansion_plots enable row level security;
revoke all on public.mansion_plots from anon, authenticated;

/** A new owner takes the lowest free plot, and Lola tells the city; a refund frees the plot and moves them out. */
create or replace function public.mansion_on_entitlement() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_plot int;
  v_name text;
begin
  if new.sku <> 'waterfront-mansion' then return new; end if;
  if new.status = 'active' and not exists (select 1 from public.mansion_plots where player_id = new.player_id) then
    select min(g) into v_plot from generate_series(1, 10) g where not exists (select 1 from public.mansion_plots m where m.plot = g);
    if v_plot is null then return new; end if;
    insert into public.mansion_plots (plot, player_id, stripe_session_id) values (v_plot, new.player_id, new.stripe_session_id);
    select public.chat_filter(display_name) into v_name from public.players where id = new.player_id;
    insert into public.news_items (id, kind, headline, body, cast_ids, publish_on, status)
    values (left('mansion-' || replace(new.player_id::text, '-', ''), 40) || '-' || to_char(now(), 'YYYYMMDDHH24MI'), 'city',
            left('Billionaire''s Row has a new neighbor: plot ' || v_plot, 110),
            left('Babe. @' || v_name || ' just bought plot ' || v_plot || ' on Billionaire''s Row, the Astoria waterfront. Glass, stone, '
                 || 'their name on the gate, and an upkeep bill the size of a studio''s rent. Wave from the ferry. Lola Lowdown', 600),
            '{lola}', public.ny_today(), 'approved')
    on conflict (id) do nothing;
  elsif new.status <> 'active' then
    delete from public.mansion_plots where player_id = new.player_id;
    update public.players set home_id = public.cheapest_home(), next_rent_due = public.ny_today() + 7
     where id = new.player_id and home_id = 'waterfront_mansion';
  end if;
  return new;
end;
$$;
drop trigger if exists entitlements_mansion on public.entitlements;
create trigger entitlements_mansion after insert or update of status on public.entitlements
  for each row execute function public.mansion_on_entitlement();

/** Eviction's destination: the cheapest home anyone can live in (not a dorm, not a Couture home). */
create or replace function public.cheapest_home() returns text
language sql stable security definer set search_path = public
as $$ select h ->> 'id' from jsonb_array_elements(public.economy() -> 'homes') h where not h ? 'campus' and not h ? 'couture' order by (h ->> 'rent')::int limit 1 $$;

-- move_home (0072), plus: a Couture home is for its owners, and moving in costs the first week only.
create or replace function public.move_home(p_home text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  uid uuid := auth.uid();
  e jsonb := public.economy();
  home jsonb;
  me public.players;
  today date := public.ny_today();
  v_every interval := (public.city() -> 'economy' -> 'bills' ->> 'every')::interval;
  v_rent int;
  v_cost int;
begin
  perform public.tick(uid);
  select * into me from public.players where id = uid for update;
  if me.id is null or me.home_id is null then raise exception 'no_player' using errcode = '28000'; end if;
  select h into home from jsonb_array_elements(e -> 'homes') h where h ->> 'id' = p_home;
  if home is null then raise exception 'unknown_home' using errcode = '22023'; end if;
  if me.house_sku is not null then raise exception 'own_house' using errcode = '22023'; end if;
  if me.home_id = p_home then raise exception 'already_home' using errcode = '22023'; end if;
  if home ? 'campus' and not exists (select 1 from public.campus_enrolments where player_id = uid and campus = home ->> 'campus') then
    raise exception 'dorm_students_only' using errcode = '22023';
  end if;
  if home ? 'couture' and not exists (select 1 from public.entitlements where player_id = uid and sku = home ->> 'couture' and status = 'active') then
    raise exception 'owners_only' using errcode = '22023';
  end if;
  if exists (select 1 from public.bills where player_id = uid and kind = 'rent' and status = 'due') then
    raise exception 'rent_due' using errcode = '22023';
  end if;
  if me.clout < coalesce((home ->> 'moveClout')::int, 0) then raise exception 'home_needs_clout' using errcode = '22023'; end if;
  v_rent := (home ->> 'rent')::int;
  v_cost := v_rent * (1 + case when home ? 'couture' then 0 else coalesce((e -> 'moving' ->> 'brokerWeeks')::int, 1) end);
  if me.bank_cash < v_cost then raise exception 'cant_afford' using errcode = '22023'; end if;

  update public.players
     set bank_cash = bank_cash - v_cost,
         home_id = p_home,
         next_rent_due = (today + v_every)::date,
         moved_up = moved_up or v_rent > coalesce(public.rent_for(me.home_id), 0)
   where id = uid;
  perform public.ledger_once(uid, 'cash', -v_rent, 'rent', 'move:' || p_home || ':' || today);
  if v_cost > v_rent then perform public.ledger_once(uid, 'cash', -(v_cost - v_rent), 'broker_fee', 'move:' || p_home || ':' || today); end if;
  return jsonb_build_object('cash', -v_cost);
end;
$$;

-- Editions (0102), plus: the mansion is sold out only while its ten plots are taken (a refund frees one).
create or replace function public.couture_edition(p_sku text) returns jsonb
language sql stable security definer set search_path = public
as $$
  select case when c.edition_size is null then null else (
    with n as (
      select case when c.sku = 'waterfront-mansion'
                  then (select count(*) from public.mansion_plots)::int
                  else (select count(*) from public.entitlements e where e.sku = c.sku)::int end as taken,
             (select count(*) from public.entitlements e where e.sku = c.sku)::int as issued,
             (select count(*) from public.purchases u
               where u.sku = c.sku and u.status = 'pending' and u.created_at > now() - interval '35 minutes'
                 and not exists (select 1 from public.entitlements e where e.sku = u.sku and e.player_id = u.player_id))::int as held,
             case when c.sku = 'waterfront-mansion' then 10 else coalesce(c.drop_end, c.edition_size) end as last
    )
    select jsonb_build_object('size', c.edition_size, 'drop', c.drop_no, 'dropEnd', n.last, 'issued', n.issued,
                              'left', greatest(n.last - n.taken - n.held, 0), 'soldOut', n.taken + n.held >= n.last)
      from n) end
    from public.shop_catalog c where c.sku = p_sku
$$;

-- What the map draws (0104), plus the mansions by plot with the name on the gate.
create or replace function public.couture_map() returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'yachts', coalesce((select jsonb_agg(jsonb_build_object('player', e.player_id, 'name', public.couture_map_name(e.player_id, e.sku), 'edition', e.edition_no)
                                         order by e.edition_no nulls last, e.created_at)
                          from public.entitlements e join public.players p on p.id = e.player_id
                         where e.sku = 'astoria-yacht' and e.status = 'active' and p.banned_at is null), '[]'),
    'jets', coalesce((select jsonb_agg(jsonb_build_object('player', e.player_id, 'name', public.couture_map_name(e.player_id, e.sku), 'edition', e.edition_no)
                                       order by e.edition_no nulls last)
                        from public.entitlements e join public.players p on p.id = e.player_id
                       where e.sku = 'clout-one-jet' and e.status = 'active' and p.banned_at is null
                         and exists (select 1 from public.player_sessions s where s.player_id = e.player_id and s.last_seen > now() - interval '10 minutes')), '[]'),
    'mansions', coalesce((select jsonb_agg(jsonb_build_object('player', m.player_id, 'name', public.couture_map_name(m.player_id, 'waterfront-mansion'), 'plot', m.plot)
                                           order by m.plot)
                            from public.mansion_plots m join public.players p on p.id = m.player_id where p.banned_at is null), '[]'),
    'statue', (select jsonb_build_object('player', b.player_id, 'name', public.chat_filter(p.display_name), 'week', b.week_start,
                                         'look', b.look, 'style', p.starting_style, 'outfit', to_jsonb(b.outfit))
                 from public.plaza_bookings b join public.players p on p.id = b.player_id
                where b.status = 'booked' and b.week_start = public.plaza_week_now() and p.banned_at is null),
    'myPlazaWeek', (select b.week_start from public.plaza_bookings b where b.player_id = auth.uid() and b.status = 'booked'
                     order by b.week_start desc limit 1),
    'myPlot', (select m.plot from public.mansion_plots m where m.player_id = auth.uid()))
$$;

-- The Studio's owner list (0104) works for the mansion too; its week column stays empty.
update public.shop_catalog set wearable = true where not wearable and sku = 'waterfront-mansion';

revoke all on function public.mansion_on_entitlement() from public, anon, authenticated;
revoke all on function public.cheapest_home() from public, anon, authenticated;
revoke all on function public.couture_edition(text) from public, anon, authenticated;
